-- Bổ sung lời giải từng bước cho đúng ngân hàng tổng hợp Nguyễn Trãi.
-- Không đổi dữ kiện bảo vệ hoặc bài làm học sinh. Trigger V5 giữ nguyên:
-- nội dung đổi phải được importer dev kiểm và phát hành lại sau migration.
WITH seed(code, worked) AS (VALUES
    ('NT-DH12-NB-01', $worked${"ham":"x**2+4*x+1","TXD":"R","dao_ham":"2*x + 4","y_phay_bang_0":["-2"],"y_phay_khong_xd":[],"bang":{"moc":["-oo","-2","+oo"],"dau":["-","+"],"dau_tai_diem":["0"],"chieu":["giam","tang"]},"ket_luan":{"dong_bien":["(-2; +oo)"],"nghich_bien":["(-oo; -2)"],"cuc_dai_x":[],"cuc_tieu_x":["-2"],"gia_tri_cuc_dai":[],"gia_tri_cuc_tieu":["-3"]},"cac_buoc":[{"van_ban":"Tập xác định: $\\mathbb{R}$."},{"van_ban":"Áp quy tắc đạo hàm, rút gọn.","bieu_thuc_sympy":"Derivative(x**2 + 4*x + 1, x)","ket_qua_sympy":"2*x + 4","latex":"\\dfrac{d}{d x} \\left(x^{2} + 4 x + 1\\right) = 2 x + 4"},{"van_ban":"Giải y′=0 được: -2. Điểm y′ không xác định trong miền: không có điểm thuộc miền làm đạo hàm không xác định."},{"van_ban":"Trên các khoảng (−∞; -2), (-2; +∞), dấu y′ lần lượt là -, +. Giữ riêng các khoảng hai bên điểm loại khỏi tập xác định."},{"van_ban":"Đồng biến trên (-2; +∞). Nghịch biến trên (−∞; -2). Cực đại: không có. Cực tiểu: x=-2, y=-3."}],"dap_an":{"dong_bien":["(-2; +oo)"],"nghich_bien":["(-oo; -2)"],"cuc_dai_x":[],"cuc_tieu_x":["-2"],"gia_tri_cuc_dai":[],"gia_tri_cuc_tieu":["-3"]}}$worked$::jsonb),
    ('NT-DH12-NB-02', $worked${"ham":"-x**2+6*x-2","TXD":"R","dao_ham":"6 - 2*x","y_phay_bang_0":["3"],"y_phay_khong_xd":[],"bang":{"moc":["-oo","3","+oo"],"dau":["+","-"],"dau_tai_diem":["0"],"chieu":["tang","giam"]},"ket_luan":{"dong_bien":["(-oo; 3)"],"nghich_bien":["(3; +oo)"],"cuc_dai_x":["3"],"cuc_tieu_x":[],"gia_tri_cuc_dai":["7"],"gia_tri_cuc_tieu":[]},"cac_buoc":[{"van_ban":"Tập xác định: $\\mathbb{R}$."},{"van_ban":"Áp quy tắc đạo hàm, rút gọn.","bieu_thuc_sympy":"Derivative(-x**2 + 6*x - 2, x)","ket_qua_sympy":"6 - 2*x","latex":"\\dfrac{d}{d x} \\left(- x^{2} + 6 x - 2\\right) = 6 - 2 x"},{"van_ban":"Giải y′=0 được: 3. Điểm y′ không xác định trong miền: không có điểm thuộc miền làm đạo hàm không xác định."},{"van_ban":"Trên các khoảng (−∞; 3), (3; +∞), dấu y′ lần lượt là +, -. Giữ riêng các khoảng hai bên điểm loại khỏi tập xác định."},{"van_ban":"Đồng biến trên (−∞; 3). Nghịch biến trên (3; +∞). Cực đại: x=3, y=7. Cực tiểu: không có."}],"dap_an":{"dong_bien":["(-oo; 3)"],"nghich_bien":["(3; +oo)"],"cuc_dai_x":["3"],"cuc_tieu_x":[],"gia_tri_cuc_dai":["7"],"gia_tri_cuc_tieu":[]}}$worked$::jsonb),
    ('NT-DH12-TH-03', $worked${"ham":"x**3-12*x+5","TXD":"R","dao_ham":"3*x**2 - 12","y_phay_bang_0":["-2","2"],"y_phay_khong_xd":[],"bang":{"moc":["-oo","-2","2","+oo"],"dau":["+","-","+"],"dau_tai_diem":["0","0"],"chieu":["tang","giam","tang"]},"ket_luan":{"dong_bien":["(-oo; -2)","(2; +oo)"],"nghich_bien":["(-2; 2)"],"cuc_dai_x":["-2"],"cuc_tieu_x":["2"],"gia_tri_cuc_dai":["21"],"gia_tri_cuc_tieu":["-11"]},"cac_buoc":[{"van_ban":"Tập xác định: $\\mathbb{R}$."},{"van_ban":"Áp quy tắc đạo hàm, rút gọn.","bieu_thuc_sympy":"Derivative(x**3 - 12*x + 5, x)","ket_qua_sympy":"3*x**2 - 12","latex":"\\dfrac{d}{d x} \\left(x^{3} - 12 x + 5\\right) = 3 x^{2} - 12"},{"van_ban":"Giải y′=0 được: -2; 2. Điểm y′ không xác định trong miền: không có điểm thuộc miền làm đạo hàm không xác định."},{"van_ban":"Trên các khoảng (−∞; -2), (-2; 2), (2; +∞), dấu y′ lần lượt là +, -, +. Giữ riêng các khoảng hai bên điểm loại khỏi tập xác định."},{"van_ban":"Đồng biến trên (−∞; -2) và (2; +∞). Nghịch biến trên (-2; 2). Cực đại: x=-2, y=21. Cực tiểu: x=2, y=-11."}],"dap_an":{"dong_bien":["(-oo; -2)","(2; +oo)"],"nghich_bien":["(-2; 2)"],"cuc_dai_x":["-2"],"cuc_tieu_x":["2"],"gia_tri_cuc_dai":["21"],"gia_tri_cuc_tieu":["-11"]}}$worked$::jsonb),
    ('NT-DH12-TH-04', $worked${"ham":"(2*x+5)/(x-3)","TXD":"R \\ {3}","dao_ham":"-11/(x - 3)**2","y_phay_bang_0":[],"y_phay_khong_xd":[],"bang":{"moc":["-oo","3","+oo"],"dau":["-","-"],"dau_tai_diem":["||"],"chieu":["giam","giam"]},"ket_luan":{"dong_bien":[],"nghich_bien":["(-oo; 3)","(3; +oo)"],"cuc_dai_x":[],"cuc_tieu_x":[],"gia_tri_cuc_dai":[],"gia_tri_cuc_tieu":[]},"cac_buoc":[{"van_ban":"Tập xác định: $\\mathbb{R}\\setminus\\{3\\}$."},{"van_ban":"Áp quy tắc đạo hàm, rút gọn.","bieu_thuc_sympy":"Derivative((2*x + 5)/(x - 3), x)","ket_qua_sympy":"2/(x - 3) - (2*x + 5)/(x - 3)**2","latex":"\\dfrac{d}{d x} \\dfrac{2 x + 5}{x - 3} = \\dfrac{2}{x - 3} - \\dfrac{2 x + 5}{\\left(x - 3\\right)^{2}}"},{"van_ban":"Giải y′=0 được: không có nghiệm. Điểm y′ không xác định trong miền: không có điểm thuộc miền làm đạo hàm không xác định."},{"van_ban":"Trên các khoảng (−∞; 3), (3; +∞), dấu y′ lần lượt là -, -. Giữ riêng các khoảng hai bên điểm loại khỏi tập xác định."},{"van_ban":"Đồng biến trên không có khoảng nào. Nghịch biến trên (−∞; 3) và (3; +∞). Cực đại: không có. Cực tiểu: không có."}],"dap_an":{"dong_bien":[],"nghich_bien":["(-oo; 3)","(3; +oo)"],"cuc_dai_x":[],"cuc_tieu_x":[],"gia_tri_cuc_dai":[],"gia_tri_cuc_tieu":[]}}$worked$::jsonb),
    ('NT-DH12-VD-05', $worked${"ham":"x**4-8*x**2+7","TXD":"R","dao_ham":"4*x*(x**2 - 4)","y_phay_bang_0":["-2","0","2"],"y_phay_khong_xd":[],"bang":{"moc":["-oo","-2","0","2","+oo"],"dau":["-","+","-","+"],"dau_tai_diem":["0","0","0"],"chieu":["giam","tang","giam","tang"]},"ket_luan":{"dong_bien":["(-2; 0)","(2; +oo)"],"nghich_bien":["(-oo; -2)","(0; 2)"],"cuc_dai_x":["0"],"cuc_tieu_x":["-2","2"],"gia_tri_cuc_dai":["7"],"gia_tri_cuc_tieu":["-9","-9"]},"cac_buoc":[{"van_ban":"Tập xác định: $\\mathbb{R}$."},{"van_ban":"Áp quy tắc đạo hàm, rút gọn.","bieu_thuc_sympy":"Derivative(x**4 - 8*x**2 + 7, x)","ket_qua_sympy":"4*x**3 - 16*x","latex":"\\dfrac{d}{d x} \\left(x^{4} - 8 x^{2} + 7\\right) = 4 x^{3} - 16 x"},{"van_ban":"Giải y′=0 được: -2; 0; 2. Điểm y′ không xác định trong miền: không có điểm thuộc miền làm đạo hàm không xác định."},{"van_ban":"Trên các khoảng (−∞; -2), (-2; 0), (0; 2), (2; +∞), dấu y′ lần lượt là -, +, -, +. Giữ riêng các khoảng hai bên điểm loại khỏi tập xác định."},{"van_ban":"Đồng biến trên (-2; 0) và (2; +∞). Nghịch biến trên (−∞; -2) và (0; 2). Cực đại: x=0, y=7. Cực tiểu: x=-2, y=-9; x=2, y=-9."}],"dap_an":{"dong_bien":["(-2; 0)","(2; +oo)"],"nghich_bien":["(-oo; -2)","(0; 2)"],"cuc_dai_x":["0"],"cuc_tieu_x":["-2","2"],"gia_tri_cuc_dai":["7"],"gia_tri_cuc_tieu":["-9","-9"]}}$worked$::jsonb),
    ('NT-DH12-VD-06', $worked${"ham":"x+9/x","TXD":"R \\ {0}","dao_ham":"1 - 9/x**2","y_phay_bang_0":["-3","3"],"y_phay_khong_xd":[],"bang":{"moc":["-oo","-3","0","3","+oo"],"dau":["+","-","-","+"],"dau_tai_diem":["0","||","0"],"chieu":["tang","giam","giam","tang"]},"ket_luan":{"dong_bien":["(-oo; -3)","(3; +oo)"],"nghich_bien":["(-3; 0)","(0; 3)"],"cuc_dai_x":["-3"],"cuc_tieu_x":["3"],"gia_tri_cuc_dai":["-6"],"gia_tri_cuc_tieu":["6"]},"cac_buoc":[{"van_ban":"Tập xác định: $\\mathbb{R}\\setminus\\{0\\}$."},{"van_ban":"Áp quy tắc đạo hàm, rút gọn.","bieu_thuc_sympy":"Derivative(x + 9/x, x)","ket_qua_sympy":"1 - 9/x**2","latex":"\\dfrac{d}{d x} \\left(x + \\dfrac{9}{x}\\right) = 1 - \\dfrac{9}{x^{2}}"},{"van_ban":"Giải y′=0 được: -3; 3. Điểm y′ không xác định trong miền: không có điểm thuộc miền làm đạo hàm không xác định."},{"van_ban":"Trên các khoảng (−∞; -3), (-3; 0), (0; 3), (3; +∞), dấu y′ lần lượt là +, -, -, +. Giữ riêng các khoảng hai bên điểm loại khỏi tập xác định."},{"van_ban":"Đồng biến trên (−∞; -3) và (3; +∞). Nghịch biến trên (-3; 0) và (0; 3). Cực đại: x=-3, y=-6. Cực tiểu: x=3, y=6."}],"dap_an":{"dong_bien":["(-oo; -3)","(3; +oo)"],"nghich_bien":["(-3; 0)","(0; 3)"],"cuc_dai_x":["-3"],"cuc_tieu_x":["3"],"gia_tri_cuc_dai":["-6"],"gia_tri_cuc_tieu":["6"]}}$worked$::jsonb),
    ('NT-DH12-VDC-07', $worked${"ham":"2*x**3-15*x**2+36*x-24","TXD":"R","dao_ham":"6*x**2 - 30*x + 36","y_phay_bang_0":["2","3"],"y_phay_khong_xd":[],"bang":{"moc":["-oo","2","3","+oo"],"dau":["+","-","+"],"dau_tai_diem":["0","0"],"chieu":["tang","giam","tang"]},"ket_luan":{"dong_bien":["(-oo; 2)","(3; +oo)"],"nghich_bien":["(2; 3)"],"cuc_dai_x":["2"],"cuc_tieu_x":["3"],"gia_tri_cuc_dai":["4"],"gia_tri_cuc_tieu":["3"]},"giai_thich_them":"Hàm bậc ba đi từ −∞ tới cực đại 4, giảm tới cực tiểu 3 rồi tăng tới +∞. Do đó m nằm ngoài [3;4] cho 1 nghiệm; m=3 hoặc m=4 cho 2 nghiệm phân biệt; 3<m<4 cho 3 nghiệm.","cac_buoc":[{"van_ban":"Tập xác định: $\\mathbb{R}$."},{"van_ban":"Áp quy tắc đạo hàm, rút gọn.","bieu_thuc_sympy":"Derivative(2*x**3 - 15*x**2 + 36*x - 24, x)","ket_qua_sympy":"6*x**2 - 30*x + 36","latex":"\\dfrac{d}{d x} \\left(2 x^{3} - 15 x^{2} + 36 x - 24\\right) = 6 x^{2} - 30 x + 36"},{"van_ban":"Giải y′=0 được: 2; 3. Điểm y′ không xác định trong miền: không có điểm thuộc miền làm đạo hàm không xác định."},{"van_ban":"Trên các khoảng (−∞; 2), (2; 3), (3; +∞), dấu y′ lần lượt là +, -, +. Giữ riêng các khoảng hai bên điểm loại khỏi tập xác định."},{"van_ban":"Đồng biến trên (−∞; 2) và (3; +∞). Nghịch biến trên (2; 3). Cực đại: x=2, y=4. Cực tiểu: x=3, y=3."},{"van_ban":"Hàm bậc ba đi từ −∞ tới cực đại 4, giảm tới cực tiểu 3 rồi tăng tới +∞. Do đó m nằm ngoài [3;4] cho 1 nghiệm; m=3 hoặc m=4 cho 2 nghiệm phân biệt; 3<m<4 cho 3 nghiệm."}],"dap_an":{"ket_luan":{"dong_bien":["(-oo; 2)","(3; +oo)"],"nghich_bien":["(2; 3)"],"cuc_dai_x":["2"],"cuc_tieu_x":["3"],"gia_tri_cuc_dai":["4"],"gia_tri_cuc_tieu":["3"]},"so_nghiem_theo_m":{"m<3 hoặc m>4":1,"m=3 hoặc m=4":2,"3<m<4":3}}}$worked$::jsonb),
    ('NT-DH12-VDC-08', $worked${"ham":"-x**4+18*x**2-24","TXD":"R","dao_ham":"4*x*(9 - x**2)","y_phay_bang_0":["-3","0","3"],"y_phay_khong_xd":[],"bang":{"moc":["-oo","-3","0","3","+oo"],"dau":["+","-","+","-"],"dau_tai_diem":["0","0","0"],"chieu":["tang","giam","tang","giam"]},"ket_luan":{"dong_bien":["(-oo; -3)","(0; 3)"],"nghich_bien":["(-3; 0)","(3; +oo)"],"cuc_dai_x":["-3","3"],"cuc_tieu_x":["0"],"gia_tri_cuc_dai":["57","57"],"gia_tri_cuc_tieu":["-24"]},"giai_thich_them":"Hai đỉnh tại x=−3 và x=3 cùng có y=57; đáy giữa tại x=0 có y=−24; hai nhánh ngoài đi xuống −∞. Vì vậy số giao điểm lần lượt: 0 khi m>57, 2 khi m=57, 4 khi −24<m<57, 3 khi m=−24, 2 khi m<−24.","cac_buoc":[{"van_ban":"Tập xác định: $\\mathbb{R}$."},{"van_ban":"Áp quy tắc đạo hàm, rút gọn.","bieu_thuc_sympy":"Derivative(-x**4 + 18*x**2 - 24, x)","ket_qua_sympy":"-4*x**3 + 36*x","latex":"\\dfrac{d}{d x} \\left(- x^{4} + 18 x^{2} - 24\\right) = - 4 x^{3} + 36 x"},{"van_ban":"Giải y′=0 được: -3; 0; 3. Điểm y′ không xác định trong miền: không có điểm thuộc miền làm đạo hàm không xác định."},{"van_ban":"Trên các khoảng (−∞; -3), (-3; 0), (0; 3), (3; +∞), dấu y′ lần lượt là +, -, +, -. Giữ riêng các khoảng hai bên điểm loại khỏi tập xác định."},{"van_ban":"Đồng biến trên (−∞; -3) và (0; 3). Nghịch biến trên (-3; 0) và (3; +∞). Cực đại: x=-3, y=57; x=3, y=57. Cực tiểu: x=0, y=-24."},{"van_ban":"Hai đỉnh tại x=−3 và x=3 cùng có y=57; đáy giữa tại x=0 có y=−24; hai nhánh ngoài đi xuống −∞. Vì vậy số giao điểm lần lượt: 0 khi m>57, 2 khi m=57, 4 khi −24<m<57, 3 khi m=−24, 2 khi m<−24."}],"dap_an":{"ket_luan":{"dong_bien":["(-oo; -3)","(0; 3)"],"nghich_bien":["(-3; 0)","(3; +oo)"],"cuc_dai_x":["-3","3"],"cuc_tieu_x":["0"],"gia_tri_cuc_dai":["57","57"],"gia_tri_cuc_tieu":["-24"]},"so_nghiem_theo_m":{"m>57":0,"m=57":2,"-24<m<57":4,"m=-24":3,"m<-24":2}}}$worked$::jsonb),
    ('NT-LG11-NB-01', $worked${"cac_buoc":[{"van_ban":"Đưa góc về góc chuẩn và áp dấu.","bieu_thuc_sympy":"sin(pi/6)","ket_qua_sympy":"1/2","latex":"\\sin{\\left(\\dfrac{\\pi}{6} \\right)} = \\dfrac{1}{2}"},{"van_ban":"Rút gọn kết quả.","bieu_thuc_sympy":"1/2","ket_qua_sympy":"1/2","latex":"1 \\cdot \\dfrac{1}{2} = \\dfrac{1}{2}"}],"dap_an":"1/2"}$worked$::jsonb),
    ('NT-LG11-NB-02', $worked${"cac_buoc":[{"van_ban":"Đưa góc về góc chuẩn và áp dấu.","bieu_thuc_sympy":"cos(3*pi/4)","ket_qua_sympy":"-sqrt(2)/2","latex":"\\cos{\\left(\\dfrac{3 \\pi}{4} \\right)} = - \\dfrac{\\sqrt{2}}{2}"},{"van_ban":"Rút gọn kết quả.","bieu_thuc_sympy":"-sqrt(2)/2","ket_qua_sympy":"-sqrt(2)/2","latex":"\\dfrac{\\left(-1\\right) \\sqrt{2}}{2} = - \\dfrac{\\sqrt{2}}{2}"}],"dap_an":"-sqrt(2)/2"}$worked$::jsonb),
    ('NT-LG11-TH-03', $worked${"cac_buoc":[{"van_ban":"Đưa góc về góc chuẩn và áp dấu.","bieu_thuc_sympy":"tan(7*pi/6)","ket_qua_sympy":"sqrt(3)/3","latex":"\\tan{\\left(\\dfrac{7 \\pi}{6} \\right)} = \\dfrac{\\sqrt{3}}{3}"},{"van_ban":"Rút gọn kết quả.","bieu_thuc_sympy":"sqrt(3)/3","ket_qua_sympy":"sqrt(3)/3","latex":"\\dfrac{\\sqrt{3}}{3}"}],"dap_an":"sqrt(3)/3"}$worked$::jsonb),
    ('NT-LG11-VD-04', $worked${"cac_buoc":[{"van_ban":"Xét góc 5π/6 ở góc phần tư II, có sin dương và góc tham chiếu π/6.","latex":"\\sin(5\\pi/6)=\\sin(\\pi/6)=1/2"},{"van_ban":"Thay giá trị lượng giác vào biểu thức.","latex":"2\\sin(5\\pi/6)+3=2\\cdot\\frac{1}{2}+3=4"}],"dap_an":"4"}$worked$::jsonb),
    ('NT-LG11-VDC-05', $worked${"cac_buoc":[{"van_ban":"Phân tích đa thức theo sin x.","bieu_thuc_sympy":"2*sin(x)**2-3*sin(x)+1","ket_qua_sympy":"(sin(x)-1)*(2*sin(x)-1)","latex":"2 \\sin^{2}{\\left(x \\right)} - 3 \\sin{\\left(x \\right)} + 1 = \\left(\\sin{\\left(x \\right)} - 1\\right) \\left(2 \\sin{\\left(x \\right)} - 1\\right)"},{"van_ban":"sin x=1 hoặc sin x=1/2; trên một vòng: x=π/2 hoặc π/6,5π/6."}],"dap_an":["pi/6","pi/2","5*pi/6"],"latex":"\\left\\{\\dfrac{\\pi}{6}, \\dfrac{\\pi}{2}, \\dfrac{5 \\pi}{6}\\right\\}"}$worked$::jsonb),
    ('NT-LG11-VDC-06', $worked${"cac_buoc":[{"van_ban":"Đưa về phương trình bậc hai theo sin x.","bieu_thuc_sympy":"cos(2*x)-sin(x)","ket_qua_sympy":"1-2*sin(x)**2-sin(x)","latex":"- \\sin{\\left(x \\right)} + \\cos{\\left(2 x \\right)} = - 2 \\sin^{2}{\\left(x \\right)} - \\sin{\\left(x \\right)} + 1"},{"van_ban":"(2sin x−1)(sin x+1)=0 nên sin x=1/2 hoặc −1; x=π/6,5π/6,3π/2."}],"dap_an":["pi/6","5*pi/6","3*pi/2"],"latex":"\\left\\{\\dfrac{\\pi}{6}, \\dfrac{5 \\pi}{6}, \\dfrac{3 \\pi}{2}\\right\\}"}$worked$::jsonb),
