UPDATE solutions s SET worked_solution=seed.worked
FROM seed, problems p
WHERE p.code=seed.code AND p.origin='GIAO_VIEN_NGUYEN_TRAI'
    AND s.problem_id=p.id AND s.worked_solution IS DISTINCT FROM seed.worked;
